#include <stdio.h>

int add(int a, int b) {
    return a + b;
}

int mul(int a, int b) {
    return a * b;
}

int apply(int (*op)(int, int), int a, int b) {
    return op(a, b);
}

int main(void) {
    int (*op)(int, int) = add;

    printf("先加：%d\n", apply(op, {a}, {b}));
    op = mul;
    printf("再乘：%d\n", apply(op, {a}, {b}));
    return 0;
}
